<script setup>
import { onMounted,ref } from 'vue';import { api } from '../api';import {localizeSkill,statusText}from '../localize';const skills=ref([]),loading=ref(true),error=ref('');onMounted(async()=>{try{skills.value=(await api.skills()).map(localizeSkill)}catch(e){error.value=e.message}finally{loading.value=false}})
</script>
<template><section><div class="section-heading"><div><span class="eyebrow">模块化能力</span><h2>Agent 技能</h2><p>状态来自后端实际服务与业务能力，不是前端硬编码。</p></div></div><el-alert v-if="error" type="error" :title="error"/><el-skeleton v-if="loading" :rows="5" animated/><div v-else class="skill-grid"><article v-for="skill in skills" :key="skill.id" class="skill-card"><div class="skill-icon">{{skill.name.slice(0,1)}}</div><div class="skill-main"><h3>{{skill.name}}</h3><p>{{skill.description}}</p><small>{{skill.detail}}</small></div><el-tag :type="skill.status==='AVAILABLE'?'success':skill.status==='DEGRADED'?'warning':'info'">{{statusText[skill.status]}}</el-tag></article></div></section></template>
